insert into public.roles (code, name, type, level, description) values
  ('L0', 'Super Admin',          'internal_level', 0, 'Platform owner. Manages tenants, system configuration.'),
  ('L1', 'Managing Director',    'internal_level', 1, 'Full company control. Final approval authority.'),
  ('L2', 'General Manager',      'internal_level', 2, 'Company-wide operations. Second-level approval.'),
  ('L3', 'Project Manager',      'internal_level', 3, 'Full control within assigned projects.'),
  ('L4', 'Department Manager',   'internal_level', 4, 'Controls department workflow within own discipline.'),
  ('L5', 'Senior Engineer',      'internal_level', 5, 'Executes, reviews within own discipline.'),
  ('L6', 'Staff',                'internal_level', 6, 'Execution and submission. No approval authority.'),
  ('DC', 'Document Controller',  'functional', null, 'Manage document control, transmittals.'),
  ('PO', 'Procurement Officer',  'functional', null, 'Create PR/RFQ, receive quotations.'),
  ('QA', 'QA/QC Inspector',      'functional', null, 'Create inspection request, record results.'),
  ('HSE', 'HSE Officer',         'functional', null, 'Issue permits, log incidents.'),
  ('QS', 'QS / Cost Engineer',   'functional', null, 'Measure, value, prepare payment certificates.'),
  ('SS', 'Site Supervisor',      'functional', null, 'Create daily reports, update progress.'),
  ('SK', 'Storekeeper',          'functional', null, 'Receive materials, issue to site.'),
  ('HR', 'HR Officer',           'functional', null, 'Manage employee records, process leave.'),
  ('AC', 'Accountant',           'functional', null, 'Process invoices, prepare payments.'),
  ('BIM', 'BIM Coordinator',     'functional', null, 'Upload models, manage clash reports.'),
  ('PE', 'Planning Engineer',    'functional', null, 'Maintain schedule, report progress.'),
  ('EXT-CLT', 'Client / Owner',  'external', null, 'Contract principal. Approves milestones.'),
  ('EXT-CON', 'Consultant / PMC','external', null, 'Technical reviewer on behalf of Client.'),
  ('EXT-SUB', 'Subcontractor',   'external', null, 'Executes scope, submits progress.'),
  ('EXT-SUP', 'Supplier / Vendor','external', null, 'Receives PO, confirms delivery.'),
  ('EXT-REG', 'Regulatory Authority','external', null, 'Reviews authority submission packages.'),
  ('EXT-AUD', 'External Auditor','external', null, 'Read-only within defined audit scope.');
